1	import { access, cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
2	import { basename, dirname, join, relative, resolve } from 'pathe';
3	import { canonicalize, sha256 } from '../../../core/src/receipts/canonicalize.ts';
4	import {
5		parseWitnessReactHospitalrunReceipt,
6		REACT_HOSPITALRUN_CANONICAL_DIGEST,
7		REACT_HOSPITALRUN_FIXTURE,
8		REACT_HOSPITALRUN_RECEIPT_PATH,
9		REACT_HOSPITALRUN_RECEIPT_SHA256,
10		REACT_HOSPITALRUN_SOURCE,
11		renderWitnessReactHospitalrunReceipt,
12		WITNESS_REACT_HOSPITALRUN_CONSOLE_ERRORS,
13		WITNESS_REACT_HOSPITALRUN_FAILED_REQUESTS,
14		WITNESS_REACT_HOSPITALRUN_SCHEMA,
15		WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_DIFFERENCE,
16		witnessReactHospitalrunBehaviorDigest,
17		witnessReactHospitalrunDigest,
18		witnessReactHospitalrunRawDigest,
19		type WitnessReactHospitalrunMutation,
20		type WitnessReactHospitalrunReceipt,
21		type WitnessReactHospitalrunRun,
22	} from '../../../core/src/receipts/witness-react-hospitalrun.ts';
23	import { executeReactHospitalrunWitnessRun, HOSPITALRUN_MUTATION_SEAM } from './real-app-run.ts';
24	import { verifyLinkedWitnessProvenance } from './provenance.ts';
25	
26	const root = resolve(import.meta.dirname, '../../../..');
27	const fixtureEvidence = join(root, 'evidence/runs/react-hospitalrun');
28	const witnessEvidence = join(root, 'evidence/runs/witness-react-hospitalrun');
29	const stageRoot = join(root, '.versionless/stage/witness-react-hospitalrun');
30	const sourceOutputs = {
31		baseline: join(root, '.versionless/work/react-hospitalrun/baseline/build-run1'),
32		migrated: join(root, '.versionless/work/react-hospitalrun/target/build-vite-run1'),
33	} as const;
34	
35	async function exists(path: string): Promise<boolean> {
36		return access(path).then(
37			() => true,
38			() => false,
39		);
40	}
41	
42	async function files(directory: string): Promise<string[]> {
43		const output: string[] = [];
44		for (const entry of await readdir(directory, { withFileTypes: true })) {
45			const path = join(directory, entry.name);
46			if (entry.isDirectory()) output.push(...(await files(path)));
47			else if (entry.isFile()) output.push(path);
48		}
49		return output.sort();
50	}
51	
52	async function stageInputs(): Promise<Record<'baseline' | 'migrated', string>> {
53		const lanes = join(stageRoot, 'lanes');
54		await rm(lanes, { recursive: true, force: true });
55		const staged = { baseline: join(lanes, 'baseline'), migrated: join(lanes, 'migrated') };
56		for (const lane of ['baseline', 'migrated'] as const) {
57			if (!(await exists(sourceOutputs[lane])))
58				throw new Error(`HospitalRun ${lane} production output is absent`);
59			await mkdir(dirname(staged[lane]), { recursive: true });
60			await cp(sourceOutputs[lane], staged[lane], { recursive: true, force: false });
61		}
62		return staged;
63	}
64	
65	async function executeRuns(
66		lanes: Record<'baseline' | 'migrated', string>,
67	): Promise<WitnessReactHospitalrunRun[]> {
68		const runs: WitnessReactHospitalrunRun[] = [];
69		for (const lane of ['baseline', 'migrated'] as const)
70			for (const pass of [1, 2] as const) {
71				const raw = await executeReactHospitalrunWitnessRun({
72					lane,
73					pass,
74					laneRoot: lanes[lane],
75					receiptRoot: join(stageRoot, 'receipts'),
76				});
77				const run = raw as WitnessReactHospitalrunRun;
78				if (run.semanticDigest !== witnessReactHospitalrunRawDigest(run))
79					throw new Error(`HospitalRun ${lane} pass ${pass} raw digest differs`);
80				runs.push({ ...run, behaviorDigest: witnessReactHospitalrunBehaviorDigest(run) });
81			}
82		if (new Set(runs.map((run) => run.behaviorDigest)).size !== 1)
83			throw new Error('HospitalRun baseline/migrated behavior parity differs');
84		return runs;
85	}
86	
87	/**
88	 * Byte mutation on the migrated build: locate the visible intake-success text
89	 * in the served module, overwrite it in place with an equal-length filler,
90	 * require the journey to go red on that exact assertion, restore the original
91	 * bytes, and require the restored journey to reproduce the parity behavior
92	 * digest.
93	 */
94	async function semanticMutation(
95		laneRoot: string,
96		behaviorDigest: string,
97	): Promise<WitnessReactHospitalrunMutation> {
98		const expected = Buffer.from(HOSPITALRUN_MUTATION_SEAM);
99		const candidates: Array<{ path: string; offset: number }> = [];
100		for (const path of await files(laneRoot)) {
101			const bytes = await readFile(path);
102			const offset = bytes.indexOf(expected);
103			if (offset < 0) continue;
104			if (bytes.lastIndexOf(expected) !== offset)
105				throw new Error('HospitalRun semantic seam is not unique within its file');
106			candidates.push({ path, offset });
107		}
108		const modules = candidates.filter((candidate) => candidate.path.endsWith('.js'));
109		const target = modules[0];
110		if (
111			modules.length !== 1 ||
112			target === undefined ||
113			canonicalize(candidates.map((candidate) => candidate.path).sort()) !==
114				canonicalize([target.path, `${target.path}.map`].sort())
115		)
116			throw new Error('HospitalRun semantic seam is not a single served module and its sourcemap');
117		const before = await readFile(target.path);
118		const mutated = Buffer.from(before);
119		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
120		const beforeSha256 = sha256(before);
121		const mutatedSha256 = sha256(mutated);
122		let intendedFailure = false;
123		try {
124			await writeFile(target.path, mutated);
125			try {
126				await executeReactHospitalrunWitnessRun({
127					lane: 'migrated',
128					pass: 1,
129					laneRoot,
130					receiptRoot: join(stageRoot, 'mutation-receipt'),
131				});
132			} catch (error) {
133				const message = error instanceof Error ? error.message : String(error);
134				intendedFailure = message.includes(HOSPITALRUN_MUTATION_SEAM);
135			}
136		} finally {
137			await writeFile(target.path, before);
138		}
139		const afterRestoreSha256 = sha256(await readFile(target.path));
140		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
141			throw new Error('HospitalRun semantic mutation was not exact red and byte-restored');
142		const restored = (await executeReactHospitalrunWitnessRun({
143			lane: 'migrated',
144			pass: 1,
145			laneRoot,
146			receiptRoot: join(stageRoot, 'restoration-receipt'),
147		})) as WitnessReactHospitalrunRun;
148		const restoredBehaviorDigest = witnessReactHospitalrunBehaviorDigest(restored);
149		if (restoredBehaviorDigest !== behaviorDigest)
150			throw new Error('HospitalRun restored browser behavior differs');
151		return {
152			failure: 'witness-semantic-assertion',
153			intendedFailure: true,
154			lane: 'migrated',
155			seam: HOSPITALRUN_MUTATION_SEAM,
156			path: relative(laneRoot, target.path),
157			offset: target.offset,
158			beforeSha256,
159			mutatedSha256,
160			afterRestoreSha256,
161			restoredByteIdentically: true,
162			restoredRun: 'pass',
163			restoredBehaviorDigest,
164		};
165	}
166	
167	export async function runWitnessReactHospitalrun(): Promise<WitnessReactHospitalrunReceipt> {
168		if (
169			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
170			process.env.NPM_CONFIG_OFFLINE !== 'true'
171		)
172			throw new Error('HospitalRun Witness requires dual offline controls');
173		if (await exists(witnessEvidence)) throw new Error('HospitalRun Witness output collision');
174		const provenance = await verifyLinkedWitnessProvenance(root);
175		const canonicalBytes = await readFile(join(root, REACT_HOSPITALRUN_RECEIPT_PATH));
176		const canonical = JSON.parse(canonicalBytes.toString('utf8')) as {
177			fixture?: unknown;
178			integrity: { canonicalDigest: string };
179		};
180		if (
181			canonical.fixture !== REACT_HOSPITALRUN_FIXTURE ||
182			canonical.integrity.canonicalDigest !== REACT_HOSPITALRUN_CANONICAL_DIGEST ||
183			sha256(canonicalBytes) !== REACT_HOSPITALRUN_RECEIPT_SHA256
184		)
185			throw new Error('HospitalRun canonical build receipt identity differs');
186		const lanes = await stageInputs();
187		const runs = await executeRuns(lanes);
188		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
189		const blockedServiceWorker = {
190			registration: 'application-register-refused-by-context' as const,
191			checkpoints: runs[0]!.blockedServiceWorkerRuntime.checkpoints,
192			emittedOutputFiles: runs
193				.flatMap((run) => run.blockedServiceWorkerRuntime.emittedOutputFiles)
194				.filter(
195					(file, index, all) =>
196						all.findIndex((item) => canonicalize(item) === canonicalize(file)) === index,
197				)
198				.sort((left, right) => left.path.localeCompare(right.path)),
199			requests: runs[0]!.blockedServiceWorkerRuntime.requests,
200			requestTally: runs[0]!.blockedServiceWorkerRuntime.requestTally,
201			workerEvents: [] as [],
202		};
203		const artifacts = join(fixtureEvidence, 'artifacts');
204		await mkdir(artifacts, { recursive: true });
205		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
206			flag: 'wx',
207		});
208		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
209			flag: 'wx',
210		});
211		const receipt: WitnessReactHospitalrunReceipt = {
212			schemaVersion: WITNESS_REACT_HOSPITALRUN_SCHEMA,
213			result: 'pass',
214			fixture: REACT_HOSPITALRUN_FIXTURE,
215			source: REACT_HOSPITALRUN_SOURCE,
216			provenance,
217			canonicalReceipt: {
218				path: REACT_HOSPITALRUN_RECEIPT_PATH,
219				canonicalDigest: canonical.integrity.canonicalDigest,
220				sha256: sha256(canonicalBytes),
221			},
222			runs,
223			mutation,
224			blockedServiceWorker,
225			serviceWorkerDifference: WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_DIFFERENCE,
226			consoleErrors: WITNESS_REACT_HOSPITALRUN_CONSOLE_ERRORS,
227			failedRequests: WITNESS_REACT_HOSPITALRUN_FAILED_REQUESTS,
228			scrollSurface: runs[0]!.scrollSurface,
229			persistence: {
230				store: 'browser-local-pouchdb',
231				stubbed: false,
232				survivesOnlineReload: true,
233			},
234			readiness: {
235				reactLineage: { ready: 1, total: 4, counted: false },
236				overall: { ready: 3, total: 12 },
237			},
238			locality: { mode: 'offline', successfulNonLoopback: 0, osWideIsolation: false },
239			nonclaims: [
240				'This is one React lineage under direct Witness and does not establish generic React or create-react-app support.',
241				'The React lineage readiness score is unchanged; this vertical is not counted before Judge audit.',
242				'The patient record is created inside the browser by the application itself against its own PouchDB store; no database was stubbed, seeded, or answered by the harness, and no real patient data is involved.',
243				'Scroll is claimed only for the appointment schedule, the one visited route whose document overflows the 1280x720 viewport; the other visited routes report scrollHeight equal to clientHeight and are not claimed as scroll coverage.',
244				'Drag is not tested because the visited routes have no genuine drag surface.',
245				'Service-worker registration is refused at the browser context in both lanes. The refusal is not silenced: each lane emits exactly the console errors and failed requests pinned in this receipt, and anything outside those inventories fails the run.',
246				'The baseline still emits and registers a create-react-app service-worker.js while the migrated build emits none; that difference is recorded as a real behavioral migration difference rather than normalized away.',
247				'Neither lane has a silent console. The application itself calls serviceWorker.register() in both lanes, so both are noisy and noisy in different ways: the baseline serves its retained worker script and its own error handler reports the refused registration, while the migrated build has no worker script to serve and the registration probe 404s. A console-silent migrated lane would require changing the application source, which this migration deliberately does not do.',
248				'Locality is process-scoped and does not establish operating-system-wide isolation.',
249				'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
250			],
251			integrity: { algorithm: 'sha256', canonicalDigest: '' },
252		};
253		receipt.integrity.canonicalDigest = witnessReactHospitalrunDigest(receipt);
254		parseWitnessReactHospitalrunReceipt(receipt);
255		await mkdir(witnessEvidence, { recursive: true });
256		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonicalize(receipt)}\n`, {
257			flag: 'wx',
258		});
259		await writeFile(
260			join(witnessEvidence, 'receipt.md'),
261			renderWitnessReactHospitalrunReceipt(receipt),
262			{ flag: 'wx' },
263		);
264		return receipt;
265	}
266	
267	export async function verifyWitnessReactHospitalrun(
268		output = witnessEvidence,
269	): Promise<WitnessReactHospitalrunReceipt> {
270		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
271		const receipt = parseWitnessReactHospitalrunReceipt(
272			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
273		);
274		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
275			throw new Error('HospitalRun linked Witness provenance differs');
276		const canonicalBytes = await readFile(join(root, receipt.canonicalReceipt.path));
277		if (sha256(canonicalBytes) !== receipt.canonicalReceipt.sha256)
278			throw new Error('HospitalRun canonical receipt bytes drifted');
279		if (
280			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
281			renderWitnessReactHospitalrunReceipt(receipt)
282		)
283			throw new Error('HospitalRun human Witness receipt differs');
284		const serialized = canonicalize(receipt);
285		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
286			throw new Error('HospitalRun receipt leaks host identity');
287		return receipt;
288	}
289	
290	export async function main(args = process.argv.slice(2)): Promise<void> {
291		const publishIndex = args.indexOf('--publish');
292		const verifyIndex = args.indexOf('--verify');
293		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
294			const output = resolve(root, args[publishIndex + 1]!);
295			if (output !== witnessEvidence) throw new Error('HospitalRun publish path differs');
296			const receipt = await runWitnessReactHospitalrun();
297			process.stdout.write(
298				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
299			);
300			return;
301		}
302		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
303			const receipt = await verifyWitnessReactHospitalrun(resolve(root, args[verifyIndex + 1]!));
304			process.stdout.write(
305				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
306			);
307			return;
308		}
309		throw new Error(
310			'HospitalRun Witness runner requires --run-twice --publish <dir> or --verify <dir>',
311		);
312	}
313	
314	if (basename(process.argv[1] ?? '') === 'react-hospitalrun-run.ts')
315		main().catch((error: unknown) => {
316			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
317			process.exitCode = 1;
318		});
