/** Temporary surface probe for the angular-factoriolab witness unit. Deleted before completion. */
import { chromium, type Page } from 'playwright';
import { resolve, join } from 'pathe';
import { startStaticServer } from '../witness/real-app-run.ts';

const root = resolve(import.meta.dirname, '../../../..');
const chromiumExecutable = join(
	root,
	'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
);

const lane =
	process.argv[2] === 'baseline'
		? join(root, '.versionless/cache/angular-factoriolab-baseline/rebuild/dist-1')
		: join(root, '.versionless/stage/angular-factoriolab-m2/dist-a');

const out = (line: string): void => {
	process.stdout.write(`${line}\n`);
};

const server = await startStaticServer(lane, { profile: 'current-witness' });
const browser = await chromium.launch({ executablePath: chromiumExecutable, headless: true });
const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
await context.route('**/*', async (route) => {
	const url = route.request().url();
	if (url.startsWith(server.origin)) {
		await route.continue();
		return;
	}
	await route.fulfill({ status: 204, contentType: 'text/plain', body: '' });
});
const page = await context.newPage();
const consoleErrors: string[] = [];
const failed: string[] = [];
page.on('console', (message) => {
	if (message.type() === 'error') consoleErrors.push(message.text());
});
page.on('pageerror', (error) => consoleErrors.push(`pageerror: ${error.message}`));
page.on('requestfailed', (request) =>
	failed.push(
		`${request.method()} ${request.url().replace(server.origin, '{origin}')} ${request.failure()?.errorText ?? ''}`,
	),
);
await page.goto(server.origin, { waitUntil: 'load' });
await page.waitForTimeout(6000);

const table = async (label: string): Promise<void> => {
	const snapshot = await page.evaluate(() => {
		const rows = [...document.querySelectorAll('lab-list table tr')].map((row) =>
			[...row.querySelectorAll('th,td')]
				.map((cell) => (cell as HTMLElement).innerText.replace(/\s+/g, ' ').trim())
				.join(' | '),
		);
		return rows.join('\n');
	});
	out(`--- TABLE ${label} (url ${page.url().replace(/^http:\/\/127\.0\.0\.1:\d+/, '{origin}')})`);
	out(snapshot);
};

const products = async (label: string): Promise<void> => {
	const snapshot = await page.evaluate(() =>
		[...document.querySelectorAll('lab-products .product-row')]
			.map((row) => {
				const icon = row.querySelector('lab-icon img');
				const input = row.querySelector('input[type=number]') as HTMLInputElement | null;
				const select = row.querySelector('select') as HTMLSelectElement | null;
