const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
const page = await context.newPage();
const consoleErrors: string[] = [];
const failed: string[] = [];
page.on('console', (message) => {
	if (message.type() === 'error') consoleErrors.push(message.text());
});
page.on('pageerror', (error) => consoleErrors.push(`pageerror: ${error.message}`));
page.on('requestfailed', (request) =>
	failed.push(`${request.method()} ${request.url()} ${request.failure()?.errorText ?? ''}`),
);
await page.goto(server.origin, { waitUntil: 'load' });
await page.waitForTimeout(8000);
process.stdout.write(`URL ${page.url()}\nTITLE ${await page.title()}\n`);
process.stdout.write('=== BODY TEXT ===\n');
process.stdout.write(`${(await page.evaluate(() => document.body.innerText)).slice(0, 5000)}\n`);
process.stdout.write('=== OUTLINE ===\n');
const outline = await page.evaluate(() => {
	const out: string[] = [];
	const walk = (element: Element, depth: number): void => {
		if (depth > 7) return;
		const tag = element.tagName.toLowerCase();
		const id = element.id ? `#${element.id}` : '';
		const raw = typeof element.className === 'string' ? element.className.trim() : '';
		const cls = raw ? `.${raw.split(/\s+/).slice(0, 5).join('.')}` : '';
		const own = [...element.childNodes]
			.filter((node) => node.nodeType === 3)
			.map((node) => node.textContent?.trim())
			.filter(Boolean)
			.join(' ')
			.slice(0, 70);
		out.push(`${'  '.repeat(depth)}${tag}${id}${cls}${own ? ` :: ${own}` : ''}`);
		for (const child of element.children) walk(child, depth + 1);
	};
	walk(document.body, 0);
	return out.join('\n');
});
