type KeyModifier = 'Alt' | 'Control' | 'Meta' | 'Shift';
/** One user-style interaction a box performed on the page. */
type PageInteraction = {
  kind: 'click';
  selector: string;
  at: string;
} | {
  kind: 'type';
  selector: string;
  at: string; /** Always recorded, redacted or not: the honest length of the typed text. */
  textLength: number;
  redacted: boolean; /** Present only with `redact: false`; capped at RECORDED_TEXT_CAP chars. */
  text?: string;
  truncated?: boolean;
} | {
  kind: 'hover';
  selector: string;
  at: string;
} | {
  kind: 'press';
  selector: string;
  key: string;
  modifiers: KeyModifier[];
  at: string;
} | {
  kind: 'drag';
  selector: string;
  to: string | {
    x: number;
    y: number;
  };
  at: string;
} | {
  kind: 'scroll';
  deltaX: number;
  deltaY: number;
  at: string;
  selector?: string;
};
/** One tracked custom DOM event observed in the page. */
type TrackedPageEvent = {
  /** ISO timestamp taken inside the page when the event fired. */at: string; /** JSON-serializable copy of `event.detail` (null when absent). */
  detail: unknown;
};
/** Receipt evidence for one visited page. */
type PageRecord = {
  id: string;
  route: string;
  environment: string;
  surface: 'dev' | 'preview';
  url: string;
  consoleMessages: BrowserConsoleMessage[];
  pageErrors: BrowserPageError[];
  failedRequests: BrowserRequestFailure[];
  networkRequests: BrowserNetworkRequest[];
  snapshots: PageSnapshot[]; /** Main-frame navigations after the initial load; empty proves no reload. */
  navigations: PageNavigation[]; /** Per event name, every occurrence observed since trackEvents(name). */
  trackedEvents: Record<string, TrackedPageEvent[]>; /** Interactions the box performed on this page (click/type/hover/press/drag/scroll), in order. */
  interactions: PageInteraction[];
};
/**
 * The box-facing page handle returned by `browser.visit(...)` and
 * `preview.browser.visit(...)`. Intentionally small: assertions go through
 * `expect.page.*`, not through a Playwright-style page object.
 */
type PageHandle = {
  readonly route: string;
  readonly environment: string;
  readonly url: string;
  reload(): Promise<void>;
  content(): Promise<string>; /** Completed browser network requests observed through CDP. */
  networkRequests(): Promise<BrowserNetworkRequest[]>; /** Applies CDP network emulation before a navigation or interaction. */
  emulateNetwork(conditions: BrowserNetworkConditions): Promise<void>; /** Clears CDP network emulation for this page. */
  clearNetworkEmulation(): Promise<void>;
  /**
   * Clicks the first element matching the selector, waiting (bounded,
   * event-driven) for it to become actionable. The minimal interaction
   * primitive for reaching a user-made UI state — for example clicking a
   * counter to a known count before an HMR edit. Each click is recorded as
   * page evidence; assertions stay in `expect.page.*`.
   */
  click(selector: string, options?: {
    timeoutMs?: number;
  }): Promise<void>;
  /**
   * Focuses the first writable element matching the selector (bounded,
   * event-driven) and types text into it — the interaction primitive for
   * reaching form-made UI state before an edit. By default the typed text is
   * redacted in page evidence (`textLength` stays honest); `redact: false`
   * records it verbatim, except into password fields, which are always
   * redacted. `keyEvents: false` inserts the text in one editing operation
   * without key events. Assertions stay in `expect.page.*`.
   */
  type(selector: string, text: string, options?: {
    clear?: boolean;
    keyEvents?: boolean;
    redact?: boolean;
    timeoutMs?: number;
  }): Promise<void>;
  /**
   * Moves the pointer over the first actionable element matching the
   * selector, so `:hover`-revealed state becomes reachable. Each hover is
   * recorded as page evidence; assertions stay in `expect.page.*`.
   */
  hover(selector: string, options?: {
    modifiers?: KeyModifier[];
    timeoutMs?: number;
  }): Promise<void>;
  /**
   * Focuses the element and presses one key, optionally chorded with
   * modifiers (for example `press('#form', 'Enter', { modifiers: ['Meta'] })`).
   * Each press is recorded as page evidence; assertions stay in
   * `expect.page.*`.
   */
  press(selector: string, key: string, options?: {
    modifiers?: KeyModifier[];
    timeoutMs?: number;
  }): Promise<void>;
  /**
   * Pointer drag from a source element to a target element or fixed
   * viewport coordinates, with interpolated intermediate moves (drag
   * libraries only track after movement past a threshold; `steps` defaults
   * to 4). Native HTML5 drag-and-drop (`draggable="true"`) is not driven by
   * synthetic pointer events and is not covered. Each drag is recorded as
   * page evidence; assertions stay in `expect.page.*`.
   */
  drag(from: string, to: string | {
    x: number;
    y: number;
  }, options?: {
    steps?: number;
    timeoutMs?: number;
  }): Promise<void>;
  /**
   * Scrolls by wheel deltas (DOM sign: positive y scrolls down) at the
   * first element matching the selector, or the viewport for `null`. The
   * driver confirms — event-driven — that something actually scrolled.
   * `gesture: true` uses a real compositor gesture with momentum instead of
   * one wheel frame. Each scroll is recorded as page evidence; assertions
   * stay in `expect.page.*`.
   */
  scroll(target: string | null, delta: {
    x?: number;
    y?: number;
  }, options?: {
    gesture?: boolean;
    timeoutMs?: number;
  }): Promise<void>;
  /**
   * Starts counting custom DOM events (for example a framework's HMR event)
   * in the live page. Observed events land in the page receipt evidence and
=== expect ===
   * scan. Defaults to every text-like artifact the build emitted.
   */
  files?: string;
};
type ArtifactJsonPredicate = (json: unknown) => boolean | Promise<boolean>;
/** What `expect.page.bodyText` checks against the page body text. */
type BodyTextExpectation = {
  contains?: string;
  notContains?: string;
};
type PageExpectApi = {
  /** Waits until the selector's trimmed text equals the expected string. */text(page: PageHandle, selector: string, expected: string, options?: ExpectWaitOptions): Promise<void>; /** Waits until the page body text contains / no longer contains fragments. */
  bodyText(page: PageHandle, expectation: BodyTextExpectation, options?: ExpectWaitOptions): Promise<void>;
  /**
   * Waits until the selector's element carries the attribute. With a string
   * `expected`, waits until the attribute equals that value; with `null`,
   * waits until the element exists without the attribute (absence).
   */
  attribute(page: PageHandle, selector: string, attributeName: string, expected?: string | null, options?: ExpectWaitOptions): Promise<void>; /** Waits until the selector matches an element in the DOM. */
  exists(page: PageHandle, selector: string, options?: ExpectWaitOptions): Promise<void>; /** Waits until the selector matches exactly the expected number of elements. */
  count(page: PageHandle, selector: string, expected: number, options?: ExpectWaitOptions): Promise<void>; /** Waits until the selector matches a visible element. */
  visible(page: PageHandle, selector: string, options?: ExpectWaitOptions): Promise<void>; /** Waits until every given computed style property matches. */
  computedStyle(page: PageHandle, selector: string, styles: Record<string, string>, options?: ExpectWaitOptions): Promise<void>;
  /**
   * Declaratively checks the recorded page evidence (navigations, console
   * errors, failed requests, tracked events) and reports every mismatch at
   * once. Event expectations wait (bounded) for their counts; the numeric
   * checks compare what the page record holds at that point.
   */
  outcome(page: PageHandle, expectation: PageOutcomeExpectation, options?: ExpectWaitOptions): Promise<void>;
  /**
   * Shortcut for the common healthy-page check: no post-load navigations,
   * no console/page errors, and no failed requests.
   */
  clean(page: PageHandle, options?: ExpectWaitOptions): Promise<void>;
};
/** What `expect.response.matches` checks against an environment response. */
type ResponseExpectation = {
  status?: number;
  ok?: boolean; /** Substring match against the lowercased content-type header. */
  contentType?: string; /** Substring match against the response body. */
  contains?: string;
};
type ExpectApi = {
  /**
   * The only edit/HMR assertion: declares the expected reaction to one edit
   * across every named environment (and the reserved `server` key), waits
   * for each to settle, then diffs expectation against the recorded outcome
   * and reports all mismatches at once.
   */
  edit(change: EditReceipt, expectation: EditExpectation, options?: ExpectWaitOptions): Promise<void>;
  page: PageExpectApi;
  html: {
    contains(html: string, fragment: string): Promise<void>;
  };
  response: {
    /** Asserts status / content-type / body facts of an environment fetch. */matches(response: EnvironmentResponse, expectation: ResponseExpectation): Promise<void>;
  };
  build: {
    environment(build: BuildHandle, name: string): Promise<void>;
    artifact(build: BuildHandle, path: string): Promise<void>;
    /**
     * Scans the build's emitted text artifacts and fails if any forbidden
     * string appears, listing every file and string that matched. The
     * canonical leakage check: `expect.build.forbids(build, ['node:fs'])`.
     */
    forbids(build: BuildHandle, forbidden: string[], options?: BuildForbidsOptions): Promise<void>;
  };
  artifact: {
    exists(build: BuildHandle, path: string): Promise<void>;
    text(build: BuildHandle, path: string, expectation: ArtifactTextExpectation): Promise<void>;

