/** Temporary surface probe for the angular-factoriolab witness unit. Deleted before completion. */
import { chromium, type Page } from 'playwright';
import { resolve, join } from 'pathe';
import { startStaticServer } from '../witness/real-app-run.ts';

const root = resolve(import.meta.dirname, '../../../..');
const chromiumExecutable = join(
	root,
	'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
);

const lane =
	process.argv[2] === 'baseline'
		? join(root, '.versionless/cache/angular-factoriolab-baseline/rebuild/dist-1')
		: join(root, '.versionless/stage/angular-factoriolab-m2/dist-a');

const out = (line: string): void => {
	process.stdout.write(`${line}\n`);
};

const server = await startStaticServer(lane, { profile: 'current-witness' });
const browser = await chromium.launch({ executablePath: chromiumExecutable, headless: true });
const context = await browser.newContext({ viewport: { width: 1280, height: 720 } });
await context.route('**/*', async (route) => {
	if (route.request().url().startsWith(server.origin)) {
		await route.continue();
		return;
	}
	await route.fulfill({ status: 204, contentType: 'text/plain', body: '' });
});
const page = await context.newPage();
const consoleErrors: string[] = [];
const failed: string[] = [];
page.on('console', (message) => {
	if (message.type() === 'error') consoleErrors.push(message.text());
});
page.on('pageerror', (error) => consoleErrors.push(`pageerror: ${error.message}`));
page.on('requestfailed', (request) =>
	failed.push(
		`${request.method()} ${request.url().replace(server.origin, '{origin}')} ${request.failure()?.errorText ?? ''}`,
	),
);
const navigations: string[] = [];
page.on('framenavigated', (frame) => {
	if (frame === page.mainFrame()) navigations.push(frame.url().replace(server.origin, ''));
});
await page.goto(server.origin, { waitUntil: 'load' });
await page.waitForTimeout(6000);

const snapshot = async (label: string): Promise<void> => {
	const value = await page.evaluate(() => {
		const cell = (selector: string): string =>
			(document.querySelector(selector) as HTMLElement | null)?.innerText
				.replace(/\s+/g, ' ')
				.trim() ?? '<absent>';
		const rows = [...document.querySelectorAll('lab-list table tr')].map((row) =>
			[...row.querySelectorAll('th,td')]
				.map((item) => (item as HTMLElement).innerText.replace(/\s+/g, ' ').trim())
				.join(' | '),
		);
		return {
			header2: cell('lab-list table thead tr th:nth-child(2)'),
			row1cell2: cell('lab-list table tbody tr:nth-child(1) td:nth-child(2)'),
			headers: [...document.querySelectorAll('lab-list table thead th')].map((item) =>
				(item as HTMLElement).innerText.replace(/\s+/g, ' ').trim(),
			),
			rows,
			productIcon:
				document.querySelector('lab-products .product-row lab-icon img')?.className ?? '-',
			productRate:
				(document.querySelector('lab-products input[type=number]') as HTMLInputElement | null)
					?.value ?? '-',
			productType:
				(document.querySelector('lab-products select') as HTMLSelectElement | null)?.value ??
				'-',
		};
	});
	out(
		`--- ${label} url=${page.url().replace(/^http:\/\/127\.0\.0\.1:\d+/, '')}\n${JSON.stringify(value, null, 1)}`,
	);
};

const step = async (label: string, run: (page: Page) => Promise<void>): Promise<void> => {
	out(`\n########## ${label}`);
	try {
		await run(page);
	} catch (error) {
		out(`!! ${(error instanceof Error ? error.message : String(error)).slice(0, 600)}`);
	}
};

await snapshot('initial');

await step('hover product icon tooltip', async () => {
	await page.hover('lab-products .product-row lab-icon');
	await page.waitForTimeout(600);
	out(
		`tooltip: ${JSON.stringify(
			await page.evaluate(
				() =>
					(
						document.querySelector(
							'lab-products .product-row lab-icon .tooltip',
						) as HTMLElement | null
					)?.innerText ?? '<absent>',
			),
		)}`,
	);
});

await step('picker: open, switch tab, choose item', async () => {
	await page.click('lab-products .product-row lab-icon');
	await page.waitForTimeout(500);
	out(`picker open: ${await page.evaluate(() => document.querySelector('lab-picker') !== null)}`);
	// Category tab list order: logistics, production, intermediate-products, combat, other, research
	await page.click('lab-picker .tabs lab-icon:nth-of-type(3)');
	await page.waitForTimeout(500);
	const items = await page.evaluate(() =>
		[...document.querySelectorAll('lab-picker .tab .item lab-icon img')]
			.slice(0, 24)
			.map((img) => img.className.replace('icon scale ', '').replace(' ng-star-inserted', '')),
	);
	out(`intermediate items: ${JSON.stringify(items)}`);
