import {
  Component,
  Input,
  Output,
  EventEmitter,
  ElementRef,
  HostListener,
  ChangeDetectionStrategy,
  HostBinding,
} from '@angular/core';

import { Entities, IdName } from '~/models';

@Component({
  selector: 'lab-multiselect',
  templateUrl: './multiselect.component.html',
  styleUrls: ['./multiselect.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MultiselectComponent {
  @Input() header: string;
  @Input() set enabledIds(value: string[]) {
    this.editValue = [...value];
  }
  @Input() options: IdName[];
  @Input() parent: HTMLElement;

  @Output() cancel = new EventEmitter();
  @Output() commit = new EventEmitter<string[]>();

  opening = true;
  edited = false;
  editValue: string[];
  idEnabled: Entities<boolean> = {};

  @HostBinding('style.top.px') get top() {
    return this.parent ? this.parent.getBoundingClientRect().y + 1 : 1;
  }

  @HostBinding('style.left.px') get left() {
    return this.parent ? this.parent.getBoundingClientRect().x - 8 : 1;
  }

  constructor(private element: ElementRef) {}

  @HostListener('document:click', ['$event'])
  click(event: MouseEvent) {
    if (this.opening) {
      this.opening = false;
    } else if (!this.element.nativeElement.contains(event.target)) {
      if (this.edited) {
        this.commit.emit(this.editValue);
      } else {
        this.cancel.emit();
      }
    }
  }

  clickId(id: string, event: MouseEvent) {
    this.edited = true;
    if (this.editValue.indexOf(id) === -1) {
      this.editValue.push(id);
    } else {
      this.editValue = this.editValue.filter((i) => i !== id);
    }
    event.stopPropagation();
  }
}
=== html ===
<div class="flex tween dialog-title">
  <span class="header">{{ header }}</span>
  <i
    *ngIf="edited"
    class="clickable material-icons"
    title="Cancel changes"
    (click)="cancel.emit()"
    >close</i
  >
</div>
<div
  class="flex clickable"
  *ngFor="let opt of options"
  (click)="clickId(opt.id, $event)"
>
  <div class="material-icons">
    {{
      editValue.indexOf(opt.id) === -1 ? 'check_box_outline_blank' : 'check_box'
    }}
  </div>
  <div>{{ opt.name }}</div>
</div>
=== icon.component.html ===
<div class="image">
  <img
    *ngIf="data.iconEntities[iconId] as icon"
    src="assets/transparent.gif"
    class="icon"
    [class.shadow]="hover && hoverIcon"
    [style.background-position]="icon.position"
    [style.background-image]="icon.file ? 'url(' + icon.file + ')' : ''"
    [ngClass]="iconId"
    [class.scale]="scale"
  />
  <div *ngIf="text" class="icon-text">{{ text }}</div>
</div>
<div class="overlay" *ngIf="hover && hoverIcon">
  <i class="material-icons">{{ hoverIcon }}</i>
</div>
<div
  *ngIf="hover && (recipe || item || tooltip)"
  [style.marginTop.px]="tooltipMarginTop"
  [style.marginLeft.px]="-scrollLeft"
  class="tooltip"
  (mouseenter)="hover = false"
>
  <div *ngIf="tooltip" class="title nowrap">
    {{ tooltip }}
  </div>
  <div *ngIf="recipe" class="flex">
    <lab-icon iconId="time" [text]="recipe.time" [data]="data"></lab-icon>
    <ng-container *ngFor="let ingredient of recipe.in | keyvalue">
      <lab-icon
        [iconId]="ingredient.key"
        [text]="ingredient.value"
        [data]="data"
      ></lab-icon>
    </ng-container>
    <i class="material-icons">arrow_forward</i>
    <ng-container *ngIf="recipe.out">
      <ng-container *ngFor="let output of recipe.out | keyvalue" class="flex">
        <lab-icon
          [iconId]="output.key"
          [text]="output.value"
          [data]="data"
        ></lab-icon>
      </ng-container>
    </ng-container>
    <lab-icon
      *ngIf="!recipe.out"
      [iconId]="iconId"
      [text]="1"
      [data]="data"
    ></lab-icon>
  </div>
  <div *ngIf="item?.beacon">
    <table>
      <tr>
        <td>Effectivity</td>
        <td>{{ round(item.beacon.effectivity) }}</td>
      </tr>
      <tr>
        <td>Modules</td>
