import { chromium, type Page } from 'playwright';
import { resolve, join } from 'pathe';
import { startStaticServer } from '../witness/real-app-run.ts';

const root = resolve(import.meta.dirname, '../../../..');
const chromiumExecutable = join(
	root,
	'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
);

const lane =
	process.argv[2] === 'baseline'
		? join(root, '.versionless/cache/angular-factoriolab-baseline/rebuild/dist-1')
		: join(root, '.versionless/stage/angular-factoriolab-m2/dist-a');

const out = (line: string): void => {
	process.stdout.write(`${line}\n`);
};

const server = await startStaticServer(lane, { profile: 'current-witness' });
const browser = await chromium.launch({ executablePath: chromiumExecutable, headless: true });
const context = await browser.newContext({ viewport: { width: 1280, height: 720 } });
await context.route('**/*', async (route) => {
	if (route.request().url().startsWith(server.origin)) {
		await route.continue();
		return;
	}
	await route.fulfill({ status: 204, contentType: 'text/plain', body: '' });
});
const page = await context.newPage();
const consoleErrors: string[] = [];
const failed: string[] = [];
page.on('console', (message) => {
	if (message.type() === 'error')
		consoleErrors.push(message.text().replaceAll(server.origin, '{origin}'));
});
page.on('pageerror', (error) => consoleErrors.push(`pageerror: ${error.message}`));
page.on('requestfailed', (request) =>
	failed.push(
		`${request.method()} ${request.url().replace(server.origin, '{origin}')} ${request.failure()?.errorText ?? ''}`,
	),
);
const navigations: string[] = [];
page.on('framenavigated', (frame) => {
	if (frame === page.mainFrame()) navigations.push(frame.url().replace(server.origin, ''));
});
await page.goto(server.origin, { waitUntil: 'load' });
await page.waitForTimeout(6000);

const text = async (selector: string): Promise<string> =>
	await page.evaluate(
		(value) =>
			(document.querySelector(value) as HTMLElement | null)?.innerText
				.replace(/\s+/g, ' ')
				.trim() ?? '<absent>',
		selector,
	);

const doc = async (): Promise<string> =>
	JSON.stringify(
		await page.evaluate(() => ({
			scrollHeight: document.documentElement.scrollHeight,
			clientHeight: document.documentElement.clientHeight,
			scrollY: Math.round(window.scrollY),
		})),
	);

const snapshot = async (label: string): Promise<void> => {
	const value = await page.evaluate(() => {
		const rows = [...document.querySelectorAll('lab-list table tr')].map((row) =>
			[...row.querySelectorAll('th,td')]
				.map((item) => (item as HTMLElement).innerText.replace(/\s+/g, ' ').trim())
				.join(' | '),
		);
		return {
			headers: [...document.querySelectorAll('lab-list table thead th')].map((item) =>
				(item as HTMLElement).innerText.replace(/\s+/g, ' ').trim(),
			),
			rows,
			bodyRows: document.querySelectorAll('lab-list table tbody tr').length,
			rate:
				(document.querySelector('lab-products input[type=number]') as HTMLInputElement | null)
					?.value ?? '-',
		};
	});
	out(`--- ${label} url=${page.url().replace(/^http:\/\/127\.0\.0\.1:\d+/, '')} doc=${await doc()}`);
	out(JSON.stringify(value, null, 1));
};

const step = async (label: string, run: (page: Page) => Promise<void>): Promise<void> => {
	out(`\n########## ${label}`);
	try {
		await run(page);
	} catch (error) {
		out(`!! ${(error instanceof Error ? error.message : String(error)).slice(0, 500)}`);
	}
};

await snapshot('initial');

await step('picker open + hover tab tooltip', async () => {
	await page.click('lab-products .product-row lab-icon');
	await page.waitForTimeout(400);
	out(`tabs: ${await page.evaluate(() => document.querySelectorAll('lab-picker .tabs lab-icon').length)}`);
	await page.hover('lab-picker .tabs lab-icon:nth-of-type(3)');
	await page.waitForTimeout(400);
	out(`tab tooltip: ${JSON.stringify(await text('lab-picker .tabs lab-icon:nth-of-type(3) .tooltip .title'))}`);
	await page.click('lab-picker .tabs lab-icon:nth-of-type(3)');
	await page.waitForTimeout(400);
	out(`iron-plate present: ${await page.evaluate(() => document.querySelectorAll('lab-picker .tab lab-icon:has(img.iron-plate)').length)}`);
	await page.hover('lab-picker .tab lab-icon:has(img.iron-plate)');
	await page.waitForTimeout(400);
	out(`item tooltip title: ${JSON.stringify(await text('lab-picker .tab lab-icon:has(img.iron-plate) .tooltip .title'))}`);
	await page.click('lab-picker .tab lab-icon:has(img.iron-plate)');
	await page.waitForTimeout(3000);
	out(`picker closed: ${await page.evaluate(() => document.querySelector('lab-picker') === null)}`);
	out(`product icon: ${await page.evaluate(() => document.querySelectorAll('lab-products .product-row lab-icon img.iron-plate').length)}`);
	await snapshot('iron-plate');
});

await step('rate: focus, End, type 0 -> 10', async () => {
	await page.click('lab-products input[type=number]');
	await page.keyboard.press('End');
	await page.keyboard.type('0');
	await page.keyboard.press('Tab');
	await page.waitForTimeout(3000);
	await snapshot('rate 10');
});

await step('columns: uncheck Pollution', async () => {
	await page.click('lab-list i[title="Select columns"]');
	await page.waitForTimeout(400);
	out(`multiselect header: ${JSON.stringify(await text('lab-multiselect .header'))}`);
	out(
		`options: ${JSON.stringify(
			await page.evaluate(() =>
				[...document.querySelectorAll('lab-multiselect > div.clickable')].map((item) =>
					(item as HTMLElement).innerText.replace(/\s+/g, ' ').trim(),
				),
			),
		)}`,
	);
	await page.click('lab-multiselect > div.clickable:has-text("Pollution")');
	await page.waitForTimeout(400);
	out(
		`after toggle: ${JSON.stringify(
			await text('lab-multiselect > div.clickable:has-text("Pollution")'),
		)}`,
